SELECT attempt,database,new_epoch,outcome_kind,cancelled_by,granted_epoch,granted_start_epoch,granted_start_sequence,CAST(granted_expires_at AS TEXT) AS granted_expires_at,pending_transfer,failure_reason,refusal_kind,CAST(refusal_last_renewed_at AS TEXT) AS refusal_last_renewed_at,CAST(refusal_last_seen AS TEXT) AS refusal_last_seen,refusal_gate_code,refusal_gate_detail,refusal_transfer,refusal_migration_state,refusal_store_fingerprint,refusal_holder,refusal_superseded_by,refusal_migration,refusal_store_version,refusal_supported_version,phase_kind,phase_final_epoch,phase_final_sequence,cleanup_failure_reason,CAST(cleanup_failed_at AS TEXT) AS cleanup_failed_at FROM _fleet_sync_transfers WHERE database=?1 AND outcome_kind IS NULL
